function validate([nums]) {
  if (nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.some(v => v !== -1 && (v < 1 || v > 1e9))) return 'Each value is -1 or between 1 and 10^9.';
  return null;
}

