function minDifference(nums) {
  const n = nums.length;
  let fixed = 0;
  let low = Infinity;
  let high = -Infinity;
  const gaps = [];
  for (let i = 0; i < n; i++) {
    if (nums[i] !== -1) {
      if (i + 1 < n && nums[i + 1] !== -1) {
        fixed = Math.max(fixed, Math.abs(nums[i] - nums[i + 1]));
      }
      continue;
    }
    let end = i;
    while (end + 1 < n && nums[end + 1] === -1) end++;
    const before = i > 0 ? nums[i - 1] : nums[end + 1];
    const after = end + 1 < n ? nums[end + 1] : before;
    if (before !== undefined) {
      gaps.push([before, after, end > i]);
      low = Math.min(low, before, after);
      high = Math.max(high, before, after);
    }
    i = end;
  }
  if (gaps.length === 0) return fixed;

  const fits = (d) => {
    const x = low + d;
    const y = high - d;
    for (const [before, after, canSwitch] of gaps) {
      const beforeX = Math.abs(before - x) <= d;
      const beforeY = Math.abs(before - y) <= d;
      const afterX = Math.abs(after - x) <= d;
      const afterY = Math.abs(after - y) <= d;
      if ((beforeX && afterX) || (beforeY && afterY)) continue;
      if (canSwitch && (beforeX || beforeY) && (afterX || afterY) && y - x <= d) continue;
      return false;
    }
    return true;
  };

  let left = fixed;
  let right = Math.max(fixed, high - low);
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (fits(mid)) right = mid;
    else left = mid + 1;
  }
  return left;
}

