function minDifference(nums) {
  // Try every way to label the -1 slots as "x" or "y"; for one labelling the best x and y have a closed form.
  const n = nums.length;
  const holes = [];
  for (let i = 0; i < n; i++) if (nums[i] === -1) holes.push(i);
  let best = Infinity;
  for (let mask = 0; mask < (1 << holes.length); mask++) {
    const label = new Array(n).fill(0);
    holes.forEach((p, k) => { label[p] = (mask >> k) & 1 ? 2 : 1; });
    const touching = new Map([[1, []], [2, []]]);
    let cost = 0, mixed = false;
    for (let i = 0; i + 1 < n; i++) {
      const p = label[i], q = label[i + 1];
      if (!p && !q) cost = Math.max(cost, Math.abs(nums[i] - nums[i + 1]));
      else if (!p) touching.get(q).push(nums[i]);
      else if (!q) touching.get(p).push(nums[i + 1]);
      else if (p !== q) mixed = true;
    }
    const xs = touching.get(1), ys = touching.get(2);
    // x must lie within cost of every value in xs: possible exactly when cost >= half their spread.
    if (xs.length) cost = Math.max(cost, Math.ceil((Math.max(...xs) - Math.min(...xs)) / 2));
    if (ys.length) cost = Math.max(cost, Math.ceil((Math.max(...ys) - Math.min(...ys)) / 2));
    // If an x slot touches a y slot, the two allowed ranges must also come within cost of each other.
    if (mixed && xs.length && ys.length) {
      cost = Math.max(cost, Math.ceil((Math.max(...ys) - Math.min(...xs)) / 3), Math.ceil((Math.max(...xs) - Math.min(...ys)) / 3));
    }
    best = Math.min(best, cost);
  }
  return best;
}

