function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 9);
  if (size === 'large' && rand() < 0.7) {
    // A smooth random walk with a few blanked-out runs, so the gaps rather than the known pairs decide the answer.
    const step = 1 + Math.floor(rand() * 1000);
    const nums = [1 + Math.floor(rand() * 1e9)];
    for (let i = 1; i < n; i++) nums.push(Math.max(1, Math.min(1e9, nums[i - 1] + Math.floor(rand() * (2 * step + 1)) - step)));
    const runs = 1 + Math.floor(rand() * 6);
    for (let k = 0; k < runs; k++) {
      const start = Math.floor(rand() * n), length = 1 + Math.floor(rand() * 4);
      for (let i = start; i < Math.min(n, start + length); i++) nums[i] = -1;
    }
    return [nums];
  }
  const top = size === 'large' || rand() < 0.2 ? 1e9 : 5 + Math.floor(rand() * 40);
  const holes = rand() < 0.1 ? 1 : rand() < 0.1 ? 0 : 0.2 + rand() * 0.5;
  const nums = [];
  for (let i = 0; i < n; i++) {
    // Missing entries come in runs: a -1 is likelier right after another -1.
    const chance = nums[i - 1] === -1 ? Math.min(1, holes + 0.25) : holes;
    nums.push(rand() < chance ? -1 : 1 + Math.floor(rand() * top));
  }
  return [nums];
}
